 * suspended rows must never be treated as valid assignees, leads or mentions.
 */
export async function findActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await findMember(orgId, userId);
  return member !== null && member.status === "active" ? member : null;
}

