/**
 * Every id a client sends alongside an issue write — a parent, an assignee,
 * a label — must resolve to something live and inside `orgId`. A miss is
 * refused as not found rather than silently dropped, the one exception being
 * comment mentions.
 */
async function assertAssigneeIsActiveMember(
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<void> {
  if (assigneeId === null) return;
  requireFound(
    await memberRepo.findActiveMember(orgId, assigneeId),
    "Member",
    assigneeId,
  );
}

async function assertParentIsSameProjectIssue(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.archivedAt !== null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

async function assertLabelsAreOrgOwned(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const orgLabels = await labelRepo.listLabels(orgId);
  const validIds = new Set(orgLabels.map((label) => label.id));
  for (const labelId of labelIds) {
    if (!validIds.has(labelId)) {
      throw new NotFoundError("Label", labelId);
    }
  }
}

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  await assertAssigneeIsActiveMember(input.orgId, input.assigneeId);
  await assertParentIsSameProjectIssue(
    input.orgId,
    input.projectId,
    input.parentId,
  );
  await assertLabelsAreOrgOwned(input.orgId, input.labelIds);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

