/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. Both sides are only ever taken from
 * members who are *currently* active — the composer's suggestion list can go
 * stale between page load and submit, so a client-provided id is re-checked
 * here rather than trusted, exactly like a parsed `@handle`. Anyone who fails
 * that check is silently dropped, never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });
  const activeMembers = members.items.filter(
    (member) => member.status === "active",
  );

  const resolved = resolveMentions(body, activeMembers);
  const activeUserIds = new Set(activeMembers.map((member) => member.userId));
  const validClientProvided = clientProvided.filter((userId) =>
    activeUserIds.has(userId),
  );

  return [...new Set([...resolved, ...validClientProvided])];
}

